package com.aditya.fefo.controller; import com.aditya.fefo.dto.AuthDtos.*; import com.aditya.fefo.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/auth") public class AuthController {private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);}}
